import React, { useEffect, useRef } from 'react';

const HeroBackground = () => {
  const canvasRef = useRef(null);
  const mousePosition = useRef({ x: 0, y: 0 });
  const activeNodes = useRef(new Set());
  const ripples = useRef([]);
  
  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: true });
    
    const setCanvasSize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    
    setCanvasSize();
    window.addEventListener('resize', setCanvasSize);

    // Slower moving nodes with less frequent target updates
    const nodes = Array.from({ length: 25 }, () => ({
      x: Math.random() * canvas.width,
      y: Math.random() * (canvas.height * 0.7),
      targetX: 0,
      targetY: 0,
      radius: Math.random() * 1.5 + 0.8,
      baseRadius: Math.random() * 1.5 + 0.8,
      vx: 0,
      vy: 0,
      lastTargetUpdate: 0,
      targetUpdateDelay: Math.random() * 5000 + 3000,
      pulsePhase: Math.random() * Math.PI * 2,
      opacity: Math.random() * 0.15 + 0.25
    }));

    // Initialize target positions
    nodes.forEach(node => {
      node.targetX = node.x;
      node.targetY = node.y;
    });

    const createRipple = (x, y) => {
      ripples.current.push({
        x,
        y,
        radius: 0,
        maxRadius: 30,
        opacity: 0.2,
        growth: 1
      });
    };

    let scrollPosition = 0;
    const handleScroll = () => {
      scrollPosition = window.scrollY;
    };
    window.addEventListener('scroll', handleScroll);

    const animate = (timestamp) => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Calculate fade based on scroll position
      const fadeStart = window.innerHeight * 0.4;
      const fadeEnd = window.innerHeight * 0.6;
      const fadeAmount = Math.max(0, Math.min(1, 1 - (scrollPosition - fadeStart) / (fadeEnd - fadeStart)));

      // Update and draw ripples
      ripples.current = ripples.current.filter(ripple => {
        ripple.radius += ripple.growth;
        ripple.opacity *= 0.95;

        ctx.beginPath();
        ctx.arc(ripple.x, ripple.y, ripple.radius, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(96, 165, 250, ${ripple.opacity * fadeAmount})`;
        ctx.lineWidth = 1;
        ctx.stroke();

        return ripple.opacity > 0.01 && ripple.radius < ripple.maxRadius;
      });

      nodes.forEach(node => {
        // Update target less frequently
        if (timestamp - node.lastTargetUpdate > node.targetUpdateDelay) {
          node.targetX = Math.random() * canvas.width;
          node.targetY = Math.random() * (canvas.height * 0.7);
          node.lastTargetUpdate = timestamp;
          node.targetUpdateDelay = Math.random() * 5000 + 3000;
        }

        // Very gradual movement towards target
        const dx = node.targetX - node.x;
        const dy = node.targetY - node.y;
        node.vx = dx * 0.005;
        node.vy = dy * 0.005;
        
        node.x += node.vx;
        node.y += node.vy;

        // Mouse interaction without ripples
        const mouseDx = mousePosition.current.x - node.x;
        const mouseDy = mousePosition.current.y + scrollPosition - node.y;
        const mouseDistance = Math.sqrt(mouseDx * mouseDx + mouseDy * mouseDy);
        
        if (mouseDistance < 160) {
          const angle = Math.atan2(mouseDy, mouseDx);
          const force = (160 - mouseDistance) / 160;
          node.vx -= Math.cos(angle) * force * 0.02;
          node.vy -= Math.sin(angle) * force * 0.02;
        }

        // Draw connections
        nodes.forEach(node2 => {
          const dx = node2.x - node.x;
          const dy = node2.y - node.y;
          const distance = Math.sqrt(dx * dx + dy * dy);
          
          if (distance < 140 && distance > 0) {
            const opacity = (140 - distance) / 140 * fadeAmount * 0.2;
            
            // Draw connection line
            ctx.beginPath();
            ctx.strokeStyle = `rgba(96, 165, 250, ${opacity})`;
            ctx.lineWidth = 0.8;
            ctx.moveTo(node.x, node.y);
            ctx.lineTo(node2.x, node2.y);
            ctx.stroke();

            // Connection glow
            ctx.beginPath();
            ctx.strokeStyle = `rgba(96, 165, 250, ${opacity * 0.3})`;
            ctx.lineWidth = 2;
            ctx.stroke();

            // Create ripples only on very close neuron interaction
            // if (distance < 50 && Math.random() < 0.0005) {
            //   const rippleX = (node.x + node2.x) / 2;
            //   const rippleY = (node.y + node2.y) / 2;
            //   createRipple(rippleX, rippleY);
            // }
          }
        });

        // Draw node with glow
        const pulse = Math.sin(timestamp * 0.0005 + node.pulsePhase) * 0.2;
        const currentRadius = node.baseRadius + pulse;

        // Node glow
        const gradient = ctx.createRadialGradient(
          node.x, node.y, 0,
          node.x, node.y, currentRadius * 3
        );
        gradient.addColorStop(0, `rgba(96, 165, 250, ${0.2 * fadeAmount})`);
        gradient.addColorStop(1, 'rgba(96, 165, 250, 0)');
        
        ctx.beginPath();
        ctx.fillStyle = gradient;
        ctx.arc(node.x, node.y, currentRadius * 3, 0, Math.PI * 2);
        ctx.fill();

        // Node center
        ctx.beginPath();
        ctx.fillStyle = `rgba(96, 165, 250, ${0.5 * fadeAmount})`;
        ctx.arc(node.x, node.y, currentRadius, 0, Math.PI * 2);
        ctx.fill();
      });

      requestAnimationFrame(animate);
    };

    const handleMouseMove = (e) => {
      const rect = canvas.getBoundingClientRect();
      mousePosition.current = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
      };
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate(0);

    return () => {
      window.removeEventListener('resize', setCanvasSize);
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  return (
    <>
      {/* Subtle hero section glow */}
      <div 
        className="fixed inset-0 z-0 pointer-events-none"
        style={{
          background: 'radial-gradient(circle at 50% 50%, rgba(59, 130, 246, 0.03), rgba(0, 0, 0, 1) 70%)',
          height: '100vh'
        }}
      />
      
      {/* Canvas */}
      <div className="fixed inset-0 w-full h-full z-0">
        <canvas
          ref={canvasRef}
          className="absolute inset-0 w-full h-full"
          style={{
            opacity: 0.7,
            mixBlendMode: 'plus-lighter',
            backgroundColor: 'transparent',
          }}
        />
      </div>
    </>
  );
};

export default HeroBackground;