import React from "react";
import { motion } from "framer-motion";
import { ExternalLink } from "lucide-react";


const Research = () => {
  const papers = [
    {
      title: "A Hybrid Ensemble Approach for Short-Text Sentiment Analysis",
      description:
        "Developed a novel ensemble framework combining a BiLSTM model with traditional ML classifiers for enhanced sentiment analysis performance",
      status: "Under Review 2024",
      technologies: ["Deep Learning", "NLP", "Ensemble Methods"],
      type: "Preprint",
    },
    {
      title: "Conversational Text Extraction with Large Language Models",
      description:
        "Built an efficient RAG system achieving improved text extraction accuracy through hybrid retrieval mechanisms",
      status: "IEEE CINE 2024",
      technologies: ["RAG", "LLMs", "Information Retrieval"],
      type: "Conference",
    },
  ];

  return (
    <section id="research" className="relative py-32">
      
      <div className="section-container relative">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="text-center mb-20"
        >
          <h2 className="heading-2 mb-6">Research Publications</h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            Contributing to the fields of Machine Learning and Natural Language
            Processing through published research and ongoing studies.
          </p>
        </motion.div>

        {/* Papers Grid */}
        <div className="grid md:grid-cols-2 gap-8 max-w-6xl mx-auto">
          {papers.map((paper, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: index * 0.2 }}
            >
              <div className="group h-full relative bg-background-light/50 backdrop-blur-sm rounded-xl p-8 hover:bg-background-light transition-all duration-300 border border-gray-800 hover:border-accent/50">
                {/* Paper Type Badge */}
                <div className="absolute top-6 right-6 text-sm text-accent/90 bg-accent/10 px-4 py-1.5 rounded-full font-medium">
                  {paper.type}
                </div>

                {/* Content */}
                <div className="space-y-6">
                  <h3 className="text-2xl font-semibold group-hover:text-accent transition-colors pr-24">
                    {paper.title}
                  </h3>

                  <p className="text-gray-400 text-lg leading-relaxed">
                    {paper.description}
                  </p>

                  {/* Technologies */}
                  <div className="flex flex-wrap gap-2">
                    {paper.technologies.map((tech, techIndex) => (
                      <span
                        key={techIndex}
                        className="text-sm text-gray-300 bg-background/60 px-4 py-1.5 rounded-full border border-gray-800"
                      >
                        {tech}
                      </span>
                    ))}
                  </div>

                  {/* Status */}
                  <div className="flex items-center justify-between pt-6 border-t border-gray-800/50">
                    <span className="text-accent/90 font-medium">
                      {paper.status}
                    </span>
                    <ExternalLink className="h-5 w-5 text-gray-400 group-hover:text-accent transition-colors" />
                  </div>
                </div>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Current Research */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.4 }}
          className="mt-20 text-center"
        >
          <div className="inline-block bg-blue-500/10 px-8 py-4 rounded-2xl border border-blue-500/20">
            <p className="text-blue-400 text-lg">
              Currently researching Machine Unlearning and Copyright Protection
              for Diffusion Models at RespAI Lab
            </p>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default Research;
