import React, { useEffect, useRef } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import { Github, ExternalLink } from 'lucide-react';

const Projects = () => {
  const containerRef = useRef(null);
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"]
  });

  const projects = [
    {
      title: "Diffusion Fine-tuning Framework",
      description: "Custom repository for fine-tuning Stable Diffusion 1.4 using LoRA with advanced training pipelines and optimization techniques.",
      image: "/api/placeholder/800/600",
      technologies: ["PyTorch", "Diffusers", "LoRA", "HuggingFace"],
      github: "https://github.com/MLSAKIIT/stablediffusionlora",
      featured: true
    },
    {
      title: "Interview Evaluation System",
      description: "Built a retrieval based automatic interview evaluation framework using RAG pipeline with LangChain and FAISS for accurate response evaluation.",
      image: "/api/placeholder/800/600",
      technologies: ["LangChain", "FAISS", "PyTorch", "Transformers"],
      github: "https://github.com/sohambuilds/interview_eval",
      featured: true
    },
    {
      title: "Facial Emotion Recognition",
      description: "Implemented a hybrid GCN-CNN architecture to train a facial emotion recognition model achieving 78% accuracy on FER2013 dataset.",
      image: "/api/placeholder/800/600",
      technologies: ["PyTorch", "OpenCV", "GCN", "CNN"],
      github: "hhttps://huggingface.co/spaces/nowimsoham/fer",
      featured: true
    }
  ];

  return (
    <section id="projects" className="relative py-32 overflow-hidden" ref={containerRef}>
      {/* Background Elements */}
      <div className="absolute inset-0 bg-gradient-to-b from-background via-background/95 to-background" />
      
      <div className="section-container relative">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-center mb-20"
        >
          <h2 className="heading-2 mb-6">Featured Projects</h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            A showcase of my work in Machine Learning, Computer Vision, and Natural Language Processing.
          </p>
        </motion.div>

        {/* Projects */}
        <div className="space-y-32">
          {projects.map((project, index) => (
            <ProjectCard 
              key={index} 
              project={project} 
              index={index}
              progress={scrollYProgress}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

const ProjectCard = ({ project, index, progress }) => {
  const cardRef = useRef(null);
  const { scrollYProgress: cardProgress } = useScroll({
    target: cardRef,
    offset: ["start end", "end start"]
  });

  const y = useTransform(
    cardProgress,
    [0, 1],
    [100, -100]
  );

  const opacity = useTransform(
    cardProgress,
    [0, 0.2, 0.8, 1],
    [0, 1, 1, 0]
  );

  const scale = useTransform(
    cardProgress,
    [0, 0.2, 0.8, 1],
    [0.8, 1, 1, 0.8]
  );

  const rotateX = useTransform(
    cardProgress,
    [0, 0.2, 0.8, 1],
    [20, 0, 0, -20]
  );

  return (
    <motion.div
      ref={cardRef}
      style={{ 
        y,
        opacity,
        scale,
        rotateX
      }}
      className="relative"
    >
      <div className="grid md:grid-cols-2 gap-8 items-center">
        {/* Image Side */}
        {/* Image Side */}
<div className={`relative group ${index % 2 === 1 ? 'md:order-2' : ''}`}>
  <motion.div
    whileHover={{ scale: 1.02 }}
    transition={{ duration: 0.3 }}
    className="relative z-10"
  >
    <div className="relative overflow-hidden rounded-xl border border-gray-800 aspect-video bg-background-light/30">
      {/* Subtle Gradient Background */}
      <div className="absolute inset-0 bg-gradient-to-br from-accent/10 via-purple-500/5 to-transparent" />
      
      {/* Header Bar */}
      <div className="absolute top-0 left-0 right-0 h-8 bg-background/90 border-b border-gray-800 flex items-center justify-between px-4">
        <div className="flex space-x-2">
          <div className="w-3 h-3 rounded-full bg-red-500/50" />
          <div className="w-3 h-3 rounded-full bg-yellow-500/50" />
          <div className="w-3 h-3 rounded-full bg-green-500/50" />
        </div>
        <div className="text-xs text-gray-500 font-mono">
          {project.technologies[0]}.py
        </div>
      </div>
      
      {/* Code-like Content */}
      <div className="absolute inset-0 pt-8 p-4">
        <div className="flex items-start space-x-4">
          {/* Line Numbers */}
          <div className="text-gray-600 text-sm select-none font-mono">
            {Array(6).fill(0).map((_, i) => (
              <div key={i} className="h-5">{i + 1}</div>
            ))}
          </div>
          
          {/* Code Lines with colors */}
          <div className="flex-1 font-mono text-sm space-y-[0.3rem]">
            {/* Import section */}
            <div className="text-purple-400">
              import torch
            </div>
            <div className="text-purple-400">
              from transformers import *
            </div>
            <div className="text-purple-400">
              import diffusers
            </div>
            {/* Class definition */}
            <div className="text-blue-400">
              class {project.title.replace(/\s+/g, '')}:
            </div>
            {/* Method */}
            <div className="pl-4 text-accent/90">
              def __init__(self):
            </div>
            <div className="pl-8 text-green-400">
              self.model = ...
            </div>
          </div>
        </div>
      </div>
      
      {/* Bottom Gradient Overlay */}
      <div className="absolute bottom-0 left-0 right-0 h-1/2 bg-gradient-to-t from-background/95 to-transparent" />

      {/* Center Icon with Glow */}
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="relative">
          <div className="absolute inset-0 blur-2xl bg-accent/10 scale-150" />
          <Github className="w-12 h-12 text-accent/40 relative z-10" />
        </div>
      </div>

      {/* Tech Tags */}
      <div className="absolute bottom-4 right-4 flex gap-2">
        {project.technologies.slice(0, 2).map((tech, idx) => (
          <span 
            key={idx}
            className="text-xs px-2 py-1 rounded-full bg-background/80 border border-accent/20 text-accent/70 backdrop-blur-sm"
          >
            {tech}
          </span>
        ))}
      </div>
    </div>
  </motion.div>

  {/* Background Glow Effect */}
  <div className="absolute -inset-4 bg-accent/5 rounded-xl blur-xl group-hover:bg-accent/10 transition-colors duration-300 z-0" />
</div>

        {/* Content Side */}
        <div className={`space-y-6 ${index % 2 === 1 ? 'md:order-1 md:text-right' : ''}`}>
          <motion.h3 
            className="text-3xl font-bold text-white"
            whileHover={{ x: index % 2 === 1 ? -8 : 8 }}
          >
            {project.title}
          </motion.h3>
          
          <p className="text-gray-400 text-lg leading-relaxed">
            {project.description}
          </p>

          <div className={`flex flex-wrap gap-2 ${index % 2 === 1 ? 'md:justify-end' : ''}`}>
            {project.technologies.map((tech, techIndex) => (
              <span
                key={techIndex}
                className="text-sm text-accent bg-accent/10 px-4 py-1.5 rounded-full"
              >
                {tech}
              </span>
            ))}
          </div>

          <div className={`flex items-center gap-4 ${index % 2 === 1 ? 'md:justify-end' : ''}`}>
            <motion.a
              href={project.github}
              target="_blank"
              rel="noopener noreferrer"
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
              className="p-2 rounded-full bg-gray-800 hover:bg-gray-700 transition-colors"
            >
              <Github className="h-5 w-5" />
            </motion.a>
            <motion.a
              href={project.github}
              target="_blank"
              rel="noopener noreferrer"
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
              className="p-2 rounded-full bg-gray-800 hover:bg-gray-700 transition-colors"
            >
              <ExternalLink className="h-5 w-5" />
            </motion.a>
          </div>
        </div>
      </div>
    </motion.div>
  );
};

export default Projects;